/**
 * 开发者展示页：扁平信息流，无卡片。
 * 加载逻辑：先请求开发者资料 → 完成后才渲染内容 → 动画在数据就绪后再播放。
 * 失败：居中友好提示 + 重试按钮。
 */
export default function Developer() {
  const [profile, setProfile] = useState(null);
  const [err, setErr] = useState('');

  const load = async () => {
    setErr('');
    setProfile(null);
    try {
      const p = await api.devProfile();
      setProfile(fillPlaceholders(p));
    } catch {
      setErr('资料加载失败，请检查网络后重试');
      setProfile(null);
    }
  };

  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, []);

  // 加载中：只显示 loading，避免"先空再跳变"
  if (profile === null && !err) return (<div><TopBar title="开发者" /><DevLoading /></div>);
  // 加载失败：友好提示 + 重试
  if (profile === null) {
    return (
      <div>
        <TopBar title="开发者" />
        <div className="flex min-h-[40vh] flex-col items-center justify-center gap-4 px-8 text-center">
          <p className="text-[14px] text-sub">{err}</p>
          <button onClick={load} className="rounded-full bg-ink px-6 py-2.5 text-[13px] font-semibold text-white active:opacity-80">重试</button>
        </div>
      </div>
    );
  }

  const medias = MEDIA.filter((m) => profile[m.key]);

  return (
    <div>
      <TopBar title="开发者" />
      <div className="px-6 pb-10">
        {/* 头像 */}
        <Section index={0}>
          <motion.div
            initial={{ opacity: 0, scale: 0.94 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: DUR, ease: EASE }}
            className="flex justify-center pt-6"
          >
            {profile.avatar ? (
              <img src={profile.avatar} alt="开发者头像" className="h-24 w-24 rounded-full object-cover" />
            ) : (
              <span className="flex h-24 w-24 items-center justify-center rounded-full bg-ink text-[36px] font-bold text-white">
                {(profile.name === PLACEHOLDER ? '开' : profile.name[0]).toUpperCase()}
              </span>
            )}
          </motion.div>
        </Section>

        {/* 昵称 + 说明 */}
        <Section index={1}>
          <p className="mt-6 text-center text-[19px] font-semibold text-ink">{profile.name}</p>
          <p className="mx-auto mt-3 max-w-[300px] whitespace-pre-wrap text-center text-[13.5px] leading-[1.8] text-sub">
            {profile.intro}
          </p>
        </Section>

        {/* 媒体入口：低调小图标 + 文字 */}
        {medias.length > 0 && (
          <Section index={2}>
            <div className="mt-7 flex items-center justify-center gap-3">
              {medias.map((m) => (
                <a
                  key={m.key}
                  href={profile[m.key]}
                  target="_blank"
                  rel="noreferrer"
                  className="flex items-center gap-1.5 rounded-full px-3 py-1.5 text-[12px] font-medium text-faint active:bg-black/[0.04] active:text-sub"
                >
                  <span className="flex [&>svg]:h-4 [&>svg]:w-4">{m.icon}</span>
                  {m.label}
                </a>
              ))}
            </div>
          </Section>
        )}

        {/* 能力说明：扁平信息流收尾 */}
        <Section index={3}>
          <div className="mx-auto mt-8 max-w-[300px]">
            <div className="bg-line" style={{ height: 1 }} />
            <ul className="mt-5 space-y-2.5 text-[13px] leading-relaxed text-faint">
              <li>独立完成设计、前端、后端与题库建设</li>
              <li>持续打磨产品体验，欢迎反馈与建议</li>
            </ul>
            <p className="mt-6 text-center text-[11px] text-faint">{profile.name}</p>
          </div>
        </Section>

        {/* 彩蛋：宝典小猫打招呼（装饰性，不抢主信息） */}
        <Section index={4}>
          <div className="mt-10 flex justify-center pb-2">
            <CatEasterEgg />
          </div>
        </Section>
      </div>
    </div>
  );
}